from fastapi.testclient import TestClient
from app.main import app
def test_asset_requirements_lifecycle():
 c=TestClient(app); n=c.post('/api/novels',json={'title':'资产'}).json(); nid=n['id']; c.post(f'/api/novels/{nid}/chapters',json={'title':'一','content':'a'}); s=c.post(f'/api/novels/{nid}/screenplays',json={}).json(); u=f"/api/novels/{nid}/screenplays/{s['id']}"; c.post(u+'/approve'); c.post(u+'/shots'); c.post(u+'/shots/approve'); c.post(u+'/storyboard'); c.post(u+'/storyboard/approve'); planned=c.post(u+'/assets').json(); asset=planned['asset_requirements'][0]; updated=c.put(u+f"/assets/{asset['id']}",json={'kind':'IMAGE','description':'角色立绘','status':'PENDING','notes':'透明背景'}).json(); assert updated['asset_requirements'][0]['description']=='角色立绘'; assert c.post(u+'/assets/approve').status_code==200; assert c.put(u+f"/assets/{asset['id']}",json={'description':'改'}).status_code==400
